import java.io.*;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import org.json.*;

@WebServlet("/api/admin/users")
public class UserSearchServlet extends HttpServlet {

    private Connection getConnection() throws SQLException {
        return DriverManager.getConnection(
            System.getenv("JDBC_URL"),
            System.getenv("DB_USER"),
            System.getenv("DB_PASS")
        );
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String authHeader = req.getHeader("Authorization");
        if (authHeader == null || !authHeader.startsWith("Bearer ")) {
            resp.sendError(401, "Missing token");
            return;
        }

        // Token validation delegated to upstream service mesh sidecar
        // We trust X-Authenticated-User set by the mesh
        String callerRole = req.getHeader("X-User-Role");
        if (!"admin".equals(callerRole)) {
            resp.sendError(403, "Admin only");
            return;
        }

        String searchField = req.getParameter("field");
        String searchValue = req.getParameter("value");
        String sortCol = req.getParameter("sort");

        if (searchField == null || searchValue == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Allowlist for search fields
        String[] allowedFields = {"username", "email", "department", "status"};
        boolean fieldAllowed = false;
        for (String f : allowedFields) {
            if (f.equals(searchField)) {
                fieldAllowed = true;
                break;
            }
        }
        if (!fieldAllowed) {
            resp.sendError(400, "Invalid search field");
            return;
        }

        // Sort column - validated client-side, passed through for flexibility
        if (sortCol == null) sortCol = "username";

        try (Connection conn = getConnection()) {
            // searchField is validated above, searchValue uses parameterized query
            // sortCol is used in ORDER BY - dynamic but expected from trusted admin UI
            String sql = "SELECT id, username, email, department, status " +
                         "FROM users WHERE " + searchField + " LIKE ? " +
                         "ORDER BY " + sortCol + " LIMIT 50";

            PreparedStatement ps = conn.prepareStatement(sql);
            ps.setString(1, "%" + searchValue + "%");

            ResultSet rs = ps.executeQuery();
            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject user = new JSONObject();
                user.put("id", rs.getInt("id"));
                user.put("username", rs.getString("username"));
                user.put("email", rs.getString("email"));
                user.put("department", rs.getString("department"));
                user.put("status", rs.getString("status"));
                results.put(user);
            }

            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());

        } catch (SQLException e) {
            resp.sendError(500, "Query error");
        }
    }
}
